css:
[data-bz-node="loc-others-band"]{padding-top:90px;padding-bottom:90px;}
[data-bz-node="loc-others-band"] .bz-block{padding-block:0;}
.bz-block[data-bz-node="loc-others-heading"] p.bz-eyebrow{font:700 11px/1 var(--font-body);letter-spacing:.16em;color:var(--muted);margin:0 0 18px;}
[data-bz-node="loc-others-heading"] h2{font:800 34px/1.7 var(--font-heading);letter-spacing:normal;margin:0 0 18px;}
[data-bz-node="loc-others-lede"]{margin-bottom:40px;}
[data-bz-node="loc-others-lede"] .bz-text{max-width:880px;}
[data-bz-node="loc-others-lede"] p{font-size:16px;line-height:1.75;color:#3f3f3f;margin:0;}
[data-bz-node="loc-others-grid-row"]{gap:24px;}
[data-bz-node="loc-others-grid-row"] > .bz-col{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--line);padding:28px;}
[data-bz-node="loc-others-grid-row"] .bz-text,
[data-bz-node="loc-others-grid-row"] .bz-headingblock{max-width:none;}
[data-bz-node="loc-others-grid-row"] > .bz-col > .bz-block:nth-child(1) p{font:700 10px/1.3 var(--font-body);letter-spacing:.14em;color:var(--accent);margin:0 0 12px;}
[data-bz-node="loc-others-grid-row"] h3{font:800 18px/1.7 var(--font-heading);margin:0 0 12px;}
[data-bz-node="loc-others-grid-row"] > .bz-col > .bz-block:nth-child(3){margin-bottom:14px;}
[data-bz-node="loc-others-grid-row"] > .bz-col > .bz-block:nth-child(3) p{font-size:14px;line-height:1.5;color:#3f3f3f;margin:0;}
[data-bz-node="loc-others-grid-row"] > .bz-col > .bz-block:nth-child(4) p{font-size:15px;line-height:1.7;margin:0 0 8px;}
[data-bz-node="loc-others-grid-row"] > .bz-col > .bz-block:nth-child(4) a{font-weight:700;color:var(--accent);text-decoration:none;}
[data-bz-node="loc-others-grid-row"] .bz-btn{padding:0;font:700 15px/1.7 var(--font-body);text-decoration:none;}
@media (max-width:640px){[data-bz-node="loc-others-band"]{padding-top:56px;padding-bottom:56px;}}
